<template><section class="page-view"><header class="hero"><div><p>ALL PLATFORM RANKING</p><h1>统一排行榜</h1><span>按日 / 周 / 月查看命中、奖金、粉丝和盈利</span></div><button class="primary" @click="load">刷新排行榜</button></header><div class="tabs"><button v-for="p in periods" :key="p.v" :class="{active:period===p.v}" @click="period=p.v;load()">{{p.t}}</button></div><div class="ranking-grid"><article class="rank-card" v-for="c in cards" :key="c.key"><h3>{{c.title}}</h3><div class="rank-row" v-for="(r,i) in top(c.key)" :key="`${r.platform_id}-${r.user_id}`"><i>{{i+1}}</i><span><b>{{r.nickname}}</b><small>{{r.platform_name}} · ID {{r.user_id}}</small></span><strong>{{text(c.key,r)}}</strong></div><div class="empty" v-if="!top(c.key).length">当前周期暂无数据</div></article></div></section></template>
<script setup>import {ref,onMounted} from 'vue';import axios from 'axios';const period=ref('day'),rows=ref([]);const periods=[{v:'day',t:'日榜'},{v:'week',t:'周榜'},{v:'month',t:'月榜'}];const cards=[{key:'hit_rate',title:'命中榜'},{key:'bonus',title:'奖金榜'},{key:'followers',title:'粉丝榜'},{key:'profit',title:'盈利榜'}];async function load(){const r=await axios.get('/api/hub/ranking',{params:{period:period.value}});if(r.data?.code===200)rows.value=r.data.data.rows||[]}function top(k){return rows.value.slice().sort((a,b)=>Number(b[k]||0)-Number(a[k]||0)).slice(0,10)}function money(v){return Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:2})}function text(k,r){if(k==='hit_rate')return `${Number(r[k]||0).toFixed(1)}%`;if(k==='followers')return `${Math.round(Number(r[k]||0)).toLocaleString('zh-CN')}人`;return `¥${money(r[k])}`}onMounted(load)</script>
<style scoped>.tabs{display:flex;gap:7px;margin-bottom:14px}.tabs button{border:1px solid #ddd9e8;background:#fff;color:#706b7e;border-radius:9px;padding:8px 16px;cursor:pointer}.tabs button.active{background:#8068e5;color:#fff;border-color:#8068e5}.ranking-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.rank-card{background:#fff;border:1px solid #e9e7f1;border-radius:16px;padding:19px}.rank-card h3{margin:0 0 14px}.rank-row{display:grid;grid-template-columns:28px 1fr auto;align-items:center;gap:10px;padding:10px 0;border-top:1px solid #f0eef5}.rank-row>i{font-style:normal;width:25px;height:25px;border-radius:8px;display:grid;place-items:center;background:#f0ecf9;color:#8069df}.rank-row span b,.rank-row span small{display:block}.rank-row small{color:#9994a5;margin-top:3px}.rank-row strong{color:#6f59d4}@media(max-width:800px){.ranking-grid{grid-template-columns:1fr}}</style>
